-- Template: version 1 is replaced in place while nothing references it; once form rules point at it,
-- a re-run seeds the next version and deactivates the previous one (rules keep their pinned version).
DECLARE @version INT = 1;
DECLARE @ft_id INT;
DECLARE @existing INT = (SELECT ft_id FROM dbo.FormTemplate WHERE t_id = @t_id AND ft_version = @version);
IF @existing IS NOT NULL
BEGIN
    IF EXISTS (SELECT 1 FROM dbo.FormRule WHERE ft_id = @existing)
       OR EXISTS (SELECT 1 FROM dbo.xrefFormRuleQuestion x JOIN dbo.FormQuestion q ON q.fq_id = x.fq_id
                  JOIN dbo.FormSection s ON s.fs_id = q.fs_id WHERE s.ft_id = @existing)
    BEGIN
        SET @version = (SELECT MAX(ft_version) + 1 FROM dbo.FormTemplate WHERE t_id = @t_id);
        PRINT 'HVAC PM v1 is referenced by form rules; seeding as version ' + CAST(@version AS VARCHAR(10));
        UPDATE dbo.FormTemplate SET ft_active = 0, ft_modifieddatetime = GETDATE() WHERE t_id = @t_id AND ft_active = 1;
    END
    ELSE
    BEGIN
        PRINT 'Replacing unreferenced HVAC PM v1';
        DELETE q FROM dbo.FormQuestion q JOIN dbo.FormSection s ON s.fs_id = q.fs_id WHERE s.ft_id = @existing;
        DELETE FROM dbo.FormSection WHERE ft_id = @existing;
        DELETE FROM dbo.FormTemplate WHERE ft_id = @existing;
    END
END;
BEGIN TRANSACTION;
INSERT INTO dbo.FormTemplate (t_id, ft_name, ft_version, ft_active, ft_note) VALUES (@t_id, N'HVAC PM', @version, 1, N'Seeded from Universal_HVAC_PM_Master_Checklist_Data_Dictionary.xlsx by generate_form_seed.py on 2026-09-06');
