COMMIT TRANSACTION;
DECLARE @sections INT = (SELECT COUNT(*) FROM dbo.FormSection WHERE ft_id = @ft_id);
DECLARE @questions INT = (SELECT COUNT(*) FROM dbo.FormQuestion q JOIN dbo.FormSection s ON s.fs_id = q.fs_id WHERE s.ft_id = @ft_id);
PRINT 'HVAC PM template seeded: version ' + CAST(@version AS VARCHAR(10)) + ', ' + CAST(@sections AS VARCHAR(10)) + ' sections, ' + CAST(@questions AS VARCHAR(10)) + ' questions';
